74:`default_nettype none
76:module	wbxbar #(
78:parameter	NM = 4, NS=8,
79:parameter	AW = 32, DW=32,
80:parameter	[NS*AW-1:0]	SLAVE_ADDR = {
81:{ 3'b111, {(AW-3){1'b0}} },
82:{ 3'b110, {(AW-3){1'b0}} },
83:{ 3'b101, {(AW-3){1'b0}} },
84:{ 3'b100, {(AW-3){1'b0}} },
85:{ 3'b011, {(AW-3){1'b0}} },
86:{ 3'b010, {(AW-3){1'b0}} },
87:{ 4'b0010, {(AW-4){1'b0}} },
88:{ 4'b0000, {(AW-4){1'b0}} } },
89:parameter	[NS*AW-1:0]	SLAVE_MASK = (NS <= 1) ? 0
90:: { {(NS-2){ 3'b111, {(AW-3){1'b0}} }},
91:{(2){ 4'b1111, {(AW-4){1'b0}} }} },
97:parameter	LGMAXBURST=6,
104:parameter	OPT_TIMEOUT = 0,
114:parameter [0:0]	OPT_STARVATION_TIMEOUT = 1'b0
115:&& (OPT_TIMEOUT > 0),
120:parameter [0:0]	OPT_DBLBUFFER = 1'b0,
127:parameter [0:0]	OPT_LOWPOWER = 1'b1
129:) (
131:input	wire			i_clk, i_reset,
134:input	wire	[NM-1:0]	i_mcyc, i_mstb, i_mwe,
135:input	wire	[NM*AW-1:0]	i_maddr,
136:input	wire	[NM*DW-1:0]	i_mdata,
137:input	wire	[NM*DW/8-1:0]	i_msel,
140:output	wire	[NM-1:0]	o_mstall,
141:output	wire	[NM-1:0]	o_mack,
142:output	reg	[NM*DW-1:0]	o_mdata,
143:output	wire	[NM-1:0]	o_merr,
148:output	wire	[NS-1:0]	o_scyc, o_sstb, o_swe,
149:output	wire	[NS*AW-1:0]	o_saddr,
150:output	wire	[NS*DW-1:0]	o_sdata,
151:output	wire	[NS*DW/8-1:0]	o_ssel,
154:input	wire	[NS-1:0]	i_sstall, i_sack,
155:input	wire	[NS*DW-1:0]	i_sdata,
156:input	wire	[NS-1:0]	i_serr
158:);
168:localparam	TIMEOUT_WIDTH = $clog2(OPT_TIMEOUT);
172:localparam	LGNM = (NM>1) ? $clog2(NM) : 1;
179:localparam	LGNS = $clog2(NS+1);
193:wire	[NS:0]			request		[0:NM-1];
194:reg	[NS-1:0]		requested	[0:NM-1];
195:wire	[NS:0]			grant		[0:NM-1];
196:wire	[NM-1:0]		mgrant;
197:wire	[NS-1:0]		sgrant;
199:/*verilator lint_off UNUSED*/
200:wire	[LGMAXBURST-1:0]	w_mpending [0:NM-1];
201:/*verilator lint_on UNUSED*/
202:wire	[NM-1:0]		mfull, mnearfull, mempty;
203:wire	[NM-1:0]		timed_out;
205:localparam	NMFULL = (NM > 1) ? (1<<LGNM) : 1;
206:localparam	NSFULL = (1<<LGNS);
208:wire	[LGNS-1:0]	mindex		[0:NMFULL-1];
209:wire	[LGNM-1:0]	sindex		[0:NSFULL-1];
211:wire	[NMFULL-1:0]	m_cyc;
212:wire	[NMFULL-1:0]	m_stb;
213:wire	[NMFULL-1:0]	m_we;
214:wire	[AW-1:0]	m_addr		[0:NMFULL-1];
215:wire	[DW-1:0]	m_data		[0:NMFULL-1];
216:wire	[DW/8-1:0]	m_sel		[0:NMFULL-1];
217:reg	[NM-1:0]	m_stall;
219:wire	[NSFULL-1:0]	s_stall;
220:wire	[DW-1:0]	s_data		[0:NSFULL-1];
221:wire	[NSFULL-1:0]	s_ack;
222:wire	[NSFULL-1:0]	s_err;
223:wire	[NM-1:0]	dcd_stb;
225:localparam [0:0]	OPT_BUFFER_DECODER=(NS != 1 || SLAVE_MASK != 0);
235:genvar	N, M;
236:integer	iN, iM;
237:generate for(N=0; N<NM; N=N+1)
238:begin : DECODE_REQUEST
242:wire			skd_stb, skd_stall;
243:wire			skd_we;
244:wire	[AW-1:0]	skd_addr;
245:wire	[DW-1:0]	skd_data;
246:wire	[DW/8-1:0]	skd_sel;
247:wire	[NS:0]		decoded;
248:wire			iskd_ready;
251:skidbuffer #(
257:.DW(1+AW+DW+DW/8),
261:.OPT_OUTREG(0)
263:) iskid (
265:.i_clk(i_clk),
266:.i_reset(i_reset || !i_mcyc[N]),
267:.i_valid(i_mstb[N]), .o_ready(iskd_ready),
268:.i_data({ i_mwe[N], i_maddr[N*AW +: AW],
269:i_mdata[N*DW +: DW],
270:i_msel[N*DW/8 +: DW/8] }),
271:.o_valid(skd_stb), .i_ready(!skd_stall),
272:.o_data({ skd_we, skd_addr, skd_data, skd_sel })
274:);
276:assign	o_mstall[N] = !iskd_ready;
278:addrdecode #(
284:.NS(NS), .AW(AW), .DW(DW+DW/8+1),
285:.SLAVE_ADDR(SLAVE_ADDR),
286:.SLAVE_MASK(SLAVE_MASK),
287:.OPT_REGISTERED(OPT_BUFFER_DECODER)
289:) adcd(
291:.i_clk(i_clk), .i_reset(i_reset),
292:.i_valid(skd_stb && i_mcyc[N]), .o_stall(skd_stall),
293:.i_addr(skd_addr),
294:.i_data({ skd_we, skd_data, skd_sel }),
295:.o_valid(dcd_stb[N]), .i_stall(m_stall[N]&&i_mcyc[N]),
296:.o_decode(decoded), .o_addr(m_addr[N]),
297:.o_data({ m_we[N], m_data[N], m_sel[N] })
299:);
301:assign	request[N] = (m_cyc[N] && dcd_stb[N]) ? decoded : 0;
303:assign	m_cyc[N] = i_mcyc[N];
304:assign	m_stb[N] = i_mcyc[N] && dcd_stb[N] && !mfull[N];
306:end for(N=NM; N<NMFULL; N=N+1)
307:begin : UNUSED_MASTER_SIGNALS
311:assign	m_cyc[N] = 0;
312:assign	m_stb[N] = 0;
314:assign	m_we[N]   = 0;
315:assign	m_addr[N] = 0;
316:assign	m_data[N] = 0;
317:assign	m_sel[N]  = 0;
319:end endgenerate
323:always @(*)
324:begin
325:for(iM=0; iM<NS; iM=iM+1)
326:begin
328:requested[0][iM] = 0;
329:for(iN=1; iN<NM; iN=iN+1)
330:begin
335:requested[iN][iM] = requested[iN-1][iM];
340:if (request[iN-1][iM] &&
341:(grant[iN-1][iM]
342:|| (!mgrant[iN-1]||mempty[iN-1])))
343:requested[iN][iM] = 1;
344:end
345:end
346:end
349:generate for(M=0; M<NS; M=M+1)
350:begin : SLAVE_GRANT
355:reg	drop_sgrant;
359:always @(*)
360:begin
361:drop_sgrant = !m_cyc[sindex[M]];
362:if (!request[sindex[M]][M] && m_stb[sindex[M]]
363:&& mempty[sindex[M]])
364:drop_sgrant = 1;
365:if (!sgrant[M])
366:drop_sgrant = 0;
367:if (i_reset)
368:drop_sgrant = 1;
369:end
374:reg	r_sgrant;
376:initial	r_sgrant = 0;
377:always @(posedge i_clk)
378:begin
379:r_sgrant <= sgrant[M];
380:for(iN=0; iN<NM; iN=iN+1)
381:if (request[iN][M] && (!mgrant[iN] || mempty[iN]))
382:r_sgrant <= 1;
383:if (drop_sgrant)
384:r_sgrant <= 0;
385:end
387:assign	sgrant[M] = r_sgrant;
409:assign	s_data[M]  = i_sdata[M*DW +: DW];
410:assign	s_stall[M] = o_sstb[M] && i_sstall[M];
411:assign	s_ack[M]   = o_scyc[M] && i_sack[M];
412:assign	s_err[M]   = o_scyc[M] && i_serr[M];
415:end for(M=NS; M<NSFULL; M=M+1)
416:begin : UNUSED_SLAVE_SIGNALS
418:assign	s_data[M]  = 0;
419:assign	s_stall[M] = 1;
420:assign	s_ack[M]   = 0;
421:assign	s_err[M]   = 1;
423:end endgenerate
428:generate for(N=0; N<NM; N=N+1)
429:begin : ARBITRATE_REQUESTS
434:wire	[NS:0]		regrant;
435:wire	[LGNS-1:0]	reindex;
472:reg	stay_on_channel;
473:reg	requested_channel_is_available;
478:always @(*)
479:begin
480:stay_on_channel = |(request[N] & grant[N]);
482:if (mgrant[N] && !mempty[N])
483:stay_on_channel = 1;
484:end
489:always @(*)
490:begin
491:requested_channel_is_available =
492:|(request[N][NS-1:0]& ~sgrant & ~requested[N][NS-1:0]);
494:if (request[N][NS])
495:requested_channel_is_available = 1;
497:if (NM < 2)
498:requested_channel_is_available = m_stb[N];
499:end
504:reg		r_mgrant;
505:reg	[NS:0]	r_grant;
507:initial	r_grant = 0;
508:initial	r_mgrant = 0;
509:always @(posedge i_clk)
510:if (i_reset || !i_mcyc[N])
511:begin
512:r_grant  <= 0;
513:r_mgrant <= 0;
514:end else if (!stay_on_channel)
515:begin
516:if (requested_channel_is_available)
517:begin
518:r_mgrant <= 1'b1;
519:r_grant  <= request[N];
520:end else if (m_stb[N])
521:begin
522:r_mgrant <= 1'b0;
523:r_grant  <= 0;
524:end
525:end
527:assign	mgrant[N] = r_mgrant;
528:assign	grant[N]  = r_grant;
531:if (NS == 1)
532:begin : MINDEX_ONE_SLAVE
534:assign	mindex[N] = 0;
535:assign	regrant = 0;
536:assign	reindex = 0;
538:/*verilator lint_off UNUSED*/
539:wire	unused_regrant = &{ 1'b0, regrant, reindex };
542:end else begin : MINDEX_MULTIPLE_SLAVES
544:reg	[LGNS-1:0]	r_mindex;
549:reg	[NS:0]		r_regrant;
550:reg	[LGNS-1:0]	r_reindex;
554:always @(*)
555:begin
556:r_regrant = 0;
557:for(iM=0; iM<NS; iM=iM+1)
558:begin
559:if (grant[N][iM])
561:r_regrant[iM] = 1'b1;
562:else if (!sgrant[iM]&&!requested[N][iM])
563:r_regrant[iM] = 1'b1;
565:if (!request[N][iM])
566:r_regrant[iM] = 1'b0;
567:end
569:if (grant[N][NS])
570:r_regrant[NS] = 1;
571:if (!request[N][NS])
572:r_regrant[NS] = 0;
574:if (mgrant[N] && !mempty[N])
575:r_regrant = 0;
576:end
581:/*verilator lint_off BLKSEQ*/
582:always @(r_regrant, regrant)
583:begin
584:r_reindex = 0;
585:for(iM=0; iM<=NS; iM=iM+1)
586:if (r_regrant[iM])
587:r_reindex = r_reindex | iM[LGNS-1:0];
588:if (regrant == 0)
589:r_reindex = r_mindex;
590:end
591:/*verilator lint_on BLKSEQ*/
594:always @(posedge i_clk)
595:r_mindex <= reindex;
597:assign	reindex = r_reindex;
598:assign	regrant = r_regrant;
625:assign	mindex[N] = r_mindex;
627:end
629:end for (N=NM; N<NMFULL; N=N+1)
630:begin : UNUSED_MINDEXES
632:assign	mindex[N] = 0;
634:end endgenerate
640:generate for(M=0; M<NS; M=M+1)
641:begin : GEN_SINDEX
643:if (NM <= 1)
644:begin : SINDEX_SINGLE_MASTER
648:assign	sindex[M] = 0;
650:end else begin : SINDEX_MORE_THAN_ONE_MASTER
652:reg	[LGNM-1:0]	r_sindex;
656:reg	[NM-1:0]	regrant;
657:reg	[LGNM-1:0]	reindex;
659:always @(*)
660:begin
661:regrant = 0;
662:for (iN=0; iN<NM; iN=iN+1)
663:begin
666:if (grant[iN][M])
667:regrant[iN] = 1;
668:else if (!sgrant[M]&& !requested[iN][M])
669:regrant[iN] = 1;
671:if (!request[iN][M])
672:regrant[iN] = 0;
673:if (mgrant[iN] && !mempty[iN])
674:regrant[iN] = 0;
675:end
676:end
678:always @(*)
679:begin
680:reindex = 0;
684:if (regrant == 0)
685:reindex = sindex[M];
686:else for(iN=0; iN<NM; iN=iN+1)
687:if (regrant[iN])
688:reindex = reindex | iN[LGNM-1:0];
689:end
691:always @(posedge i_clk)
692:r_sindex <= reindex;
694:assign	sindex[M] = r_sindex;
